// Move with the joystick and face the walking direction.
function update(dt) {
  const speed = props.speed ?? 5;
  const x = input.axis.x;
  const y = input.axis.y;
  entity.translate(x * speed * dt, 0, -y * speed * dt);
  if (x !== 0 || y !== 0) {
    entity.rotation.y = Math.atan2(-x, y) * 180 / Math.PI;
  }
}

// Jump when the "jump" button is pressed (needs a RigidBody).
function update(dt) {
  if (input.wasPressed('jump') && entity.isOnGround()) {
    const v = entity.getVelocity();
    entity.setVelocity(v.x, props.jumpStrength ?? 7, v.z);
  }
}

// Tap (or click) the ground: walk there, going around walls.
function update(dt) {
  if (input.tapped) {
    const p = game.touchWorld();
    entity.moveTo(p.x, p.z, props.speed ?? 4);
  }
}

// Spin around the Y axis.
function update(dt) {
  entity.rotate(0, (props.speed ?? 90) * dt, 0);
}

// Chase the Player.
function update(dt) {
  const player = game.find('Player');
  if (!player) return;
  const target = player.getWorldPosition();
  entity.lookAt(target.x, entity.position.y, target.z);
  if (entity.distanceTo(player) > 1.5) {
    entity.moveToward(target.x, entity.position.y, target.z, (props.speed ?? 2) * dt);
  }
}

// Walk back and forth between two objects picked in the Inspector.
// Put this script on any number of enemies and give each its own Point A and Point B
// (empty objects make good markers). The fields below show up in the Inspector.
const properties = {
  speed: 2,          // meters per second
  pointA: object(),  // pick an object in the Inspector
  pointB: object(),
  wait: 0.5,         // seconds to pause at each end
};

let goingToB = true;
let waitLeft = 0;

function update(dt) {
  const target = goingToB ? props.pointB : props.pointA;
  if (!target) return;                       // not picked yet
  if (waitLeft > 0) { waitLeft -= dt; return; }
  const me = entity.getWorldPosition();
  const p = target.getWorldPosition();
  entity.lookAt(p.x, me.y, p.z);             // face it, staying upright
  entity.moveToward(p.x, me.y, p.z, props.speed * dt);
  if (Math.hypot(p.x - me.x, p.z - me.z) < 0.2) {
    goingToB = !goingToB;                    // turn around
    waitLeft = props.wait;
  }
}

// Spawn a Coin every second somewhere around this entity.
let timer = 0;

function update(dt) {
  timer += dt;
  if (timer >= 1) {
    timer -= 1;
    const p = entity.getWorldPosition();
    game.spawn('Coin', { x: p.x + random(-4, 4), y: p.y + 5, z: p.z + random(-4, 4) });
  }
}

// Put this on the Player.
function onCollision(other) {
  if (other.name === 'Coin' || other.hasTag('coin')) {
    other.destroy();
    game.setVar('Score', Number(game.getVar('Score') ?? 0) + 1);
    audio.play('coin');
  }
}

// Tap this object to change its color.
const colors = ['#ff5c6c', '#ffb547', '#3ecf8e', '#4f8cff', '#a855f7'];
let index = 0;

function onTap() {
  index = (index + 1) % colors.length;
  entity.setColor(colors[index]);
}

// Restart the level when falling off the map.
function update(dt) {
  if (entity.position.y < -10) {
    game.restartScene();
  }
}

// Global script: show the Score in a Text entity named "ScoreText".
function update(dt) {
  const label = game.find('ScoreText');
  if (label) label.setText('Score: ' + game.getVar('Score'));
}

// Endless-runner style lane switching.
let lane = 0; // -1, 0, 1

function update(dt) {
  if (input.swipe === 'left') lane = clamp(lane - 1, -1, 1);
  if (input.swipe === 'right') lane = clamp(lane + 1, -1, 1);
  if (input.swipe === 'up' && entity.isOnGround()) entity.applyImpulse(0, 6, 0);
  entity.position.x = lerp(entity.position.x, lane * 2, 10 * dt);
}
